import csv,math,shutil,textwrap
import cv2,numpy as np
from context import ROOT,SOURCE,STUDY,read,write,sha

def main():
    assert not STUDY.exists();STUDY.mkdir();base=STUDY.parent;old=base/'tagged_surface_v1';development=base/'joint_tag_pose_v1';fit=base/'calibration_diverse_v1/fitted-intrinsics.json';assert read(base/'calibration_diverse_v1/summary.json')['ideal_intrinsics_calibration_admitted']
