    for a,b in [('core.py','pose_estimator.py'),('pose_core.py','pose_core.py')]:shutil.copy2(SOURCE.parent/'joint_tag_pose'/a,SOURCE/b)
    shutil.copy2(old/'source_snapshot/surface_builder.py',SOURCE/'tag_library.py');shutil.copy2(base/'camera_geometry_v1/source_snapshot/envelope_math.py',SOURCE/'envelope_math.py')
    import scene_builder as builder,tag_library,envelope_math as env
    original_box=builder.box;source=(SOURCE/'tag_library.py').read_text();block=source.split('    original_box=builder.box\n',1)[1].split('    builder.box=tagged_box;entries=[]',1)[0];ns=dict(builder=builder,original_box=original_box,np=np,registry=tag_library.registry);exec(textwrap.dedent(block),ns);builder.box=ns['tagged_box']
    cameras=read(old/'projects/a_hold/calibration.json')['cameras'];cameras=[dict(c,position=[.047,c['position'][1],.055],direction=(np.array([.11,0,.037])-np.array([.047,c['position'][1],.055])).tolist()) for c in cameras if c['group']=='shaft_ends_aimed'];aimed=[c for c in cameras if c['group']=='shaft_ends_aimed'];scenes=[];inputs=[]
    for rec in read(base/'camera_geometry_v1/source-records.json'):
        if rec['physics_ms']!=.25:continue
