            row=stages[stage][int((len(stages[stage])-1)*fraction)];r={k:(v if k=='stage' else float(v)) for k,v in row.items()};cr,sr=math.cos(r['roll_rad']),math.sin(r['roll_rad']);B=env.rz(r['yaw_rad'])@env.ry(r['pitch_rad'])@np.array([[1,0,0],[0,cr,-sr],[0,sr,cr]]);o=np.array([r['body_'+k+'_m'] for k in 'xyz']);cube=B.T@(np.array([r['object_'+k+'_m'] for k in 'xyz'])-o);cubeR=B.T@np.array([r['object_r'+str(i)] for i in range(9)]).reshape(3,3);pose={n:r[n] for n in ['shoulder','elbow','wrist','finger_0','finger_1','distal_0','distal_1']};pose.update(finger=0.,distal=0.);shapes=[]
            for name,owner,c,R,h in env.boxes(p,pose):shapes.append(dict(name=name,center=c.tolist(),rotation=R.tolist(),size=(h*2).tolist(),color=[.7,.08,.06] if owner=='body' else [.12,.2,.6] if 'finger' in owner else [.35,.4,.45]))
            for v in profile['fixtures']:shapes.append(dict(name=v['name'],center=(B.T@(np.array(v['center_m'])-o)).tolist(),rotation=(B.T@np.array(v['rotation'])).tolist(),size=(np.array(v['half_m'])*2).tolist(),color=[.35,.45,.5]))
            name=rec['axis']+'_'+stage+'_'+str(fraction).replace('.','p');scenes.append(dict(id=name,role='task',axis=rec['axis'],source_time_s=r['time_s'],source_stage=stage,source_directory=rec['source_directory'],source_telemetry_sha256=sha(out/'telemetry.csv'),cameras=cameras,cube=dict(center=cube.tolist(),rotation=cubeR.tolist(),size=setup['object_size_m']),shapes=shapes));inputs.append(dict(axis=rec['axis'],source_directory=rec['source_directory'],sha256=rec['input_sha256']))
